// The family roster -- see family_members' schema comment above. One
// read returns every member with their conditions attached, since every
// screen that wants one wants the other.
export type FamilyMember = {
  id: string;
  name: string;
  relationship: string;
  includeInMealPlan: boolean;
  conditionCodes: string[];
  /** G20: free-text allergies, eating styles (RecipeDietTag) and food restrictions (FoodRestrictionKey). */
  allergies: string[];
  dietTags: string[];
  restrictions: string[];
  createdAt: string;
  /** 2026-09-27, who a meal plan feeds: see lib/householdPlan.ts. */
  portion: string;
  softFood: boolean;
  awayMeals: string[];
  livesFrom: string | null;
  livesUntil: string | null;
  ageGroup: string | null;
  sex: string | null;
};

/** What the meal plan reads about a family member, beside their food lists. */
export type FamilyMemberTable = {
  portion?: string;
  softFood?: boolean;
  awayMeals?: string[];
  livesFrom?: string | null;
  livesUntil?: string | null;
  ageGroup?: string | null;
  sex?: string | null;
};

type FamilyMemberFood = { allergies: string[]; dietTags: string[]; restrictions: string[]; awayMeals: string[] };

const FAMILY_FOOD_KINDS: [keyof FamilyMemberFood, string][] = [
  ['allergies', 'allergy'],
  ['dietTags', 'diet'],
  ['restrictions', 'restriction'],
  ['awayMeals', 'away'],
];

function cleanDate(value: string | null | undefined): string | null {
  const trimmed = (value ?? '').trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(trimmed) ? trimmed : null;
}

async function writeFamilyMemberTable(id: string, table: FamilyMemberTable): Promise<void> {
  const db = await getDatabase();
  await db.runAsync(
    'UPDATE family_members SET portion = ?, soft_food = ?, lives_from = ?, lives_until = ?, age_group = ?, sex = ? WHERE id = ?',
    table.portion || 'regular',
    table.softFood ? 1 : 0,
    cleanDate(table.livesFrom),
    cleanDate(table.livesUntil),
    table.ageGroup || null,
    table.sex || null,
    id,
  );
}

async function writeFamilyMemberFood(id: string, food: Partial<FamilyMemberFood>): Promise<void> {
  const db = await getDatabase();
  for (const [field, kind] of FAMILY_FOOD_KINDS) {
    const values = food[field];
    if (!values) continue;
    await db.runAsync('DELETE FROM family_member_food WHERE member_id = ? AND kind = ?', id, kind);
    const seen = new Set<string>();
    for (const raw of values) {
      const value = raw.trim();
      if (!value || seen.has(value.toLowerCase())) continue;
      seen.add(value.toLowerCase());
      await db.runAsync('INSERT OR IGNORE INTO family_member_food (member_id, kind, value) VALUES (?, ?, ?)', id, kind, value);
    }
  }
}

export async function getFamilyMembers(): Promise<FamilyMember[]> {
  const db = await getDatabase();
  const rows = await db.getAllAsync<{
    id: string;
    name: string;
    relationship: string;
    include_in_meal_plan: number;
    created_at: string;
    portion: string | null;
    soft_food: number | null;
    lives_from: string | null;
    lives_until: string | null;
    age_group: string | null;
    sex: string | null;
  }>(
    'SELECT id, name, relationship, include_in_meal_plan, created_at, portion, soft_food, lives_from, lives_until, age_group, sex FROM family_members ORDER BY created_at, name',
  );
  // Read past a closed vault: a member's conditions shape the meal plan and
  // scoring the way the person's own do. The Family list hides them itself
  // while family health is in the vault (components/ConditionsSection.tsx).
  const conditionRows = await db.getAllAsync<{ member_id: string; condition_code: string }>(
    '/* vault:tool */ SELECT member_id, condition_code FROM family_member_conditions ORDER BY selected_at',
  );
  const byMember = new Map<string, string[]>();
  for (const row of conditionRows) {
    if (!byMember.has(row.member_id)) byMember.set(row.member_id, []);
    byMember.get(row.member_id)!.push(row.condition_code);
  }
  const foodRows = await db.getAllAsync<{ member_id: string; kind: string; value: string }>(
    'SELECT member_id, kind, value FROM family_member_food ORDER BY selected_at, value',
  );
  const foodByMember = new Map<string, FamilyMemberFood>();
  for (const row of foodRows) {
    const field = FAMILY_FOOD_KINDS.find(([, kind]) => kind === row.kind)?.[0];
    if (!field) continue;
    if (!foodByMember.has(row.member_id)) foodByMember.set(row.member_id, { allergies: [], dietTags: [], restrictions: [], awayMeals: [] });
    foodByMember.get(row.member_id)![field].push(row.value);
  }
  return rows.map((row) => ({
    id: row.id,
    name: row.name,
    relationship: row.relationship,
    includeInMealPlan: row.include_in_meal_plan === 1,
    conditionCodes: byMember.get(row.id) ?? [],
    allergies: foodByMember.get(row.id)?.allergies ?? [],
    dietTags: foodByMember.get(row.id)?.dietTags ?? [],
    restrictions: foodByMember.get(row.id)?.restrictions ?? [],
    createdAt: row.created_at,
    portion: row.portion || 'regular',
    softFood: row.soft_food === 1,
    awayMeals: foodByMember.get(row.id)?.awayMeals ?? [],
    livesFrom: row.lives_from,
    livesUntil: row.lives_until,
    ageGroup: row.age_group,
    sex: row.sex,
  }));
}

export async function addFamilyMember(input: {
  name: string;
  relationship: string;
  conditionCodes: string[];
  includeInMealPlan?: boolean;
  allergies?: string[];
  dietTags?: string[];
  restrictions?: string[];
} & FamilyMemberTable): Promise<string> {
  const db = await getDatabase();
  const id = `family_${Date.now()}`;
  await db.runAsync(
    'INSERT INTO family_members (id, name, relationship, include_in_meal_plan) VALUES (?, ?, ?, ?)',
    id,
    input.name.trim(),
    input.relationship.trim(),
    input.includeInMealPlan === false ? 0 : 1,
  );
  for (const code of new Set(input.conditionCodes)) {
    await db.runAsync('INSERT OR IGNORE INTO family_member_conditions (member_id, condition_code) VALUES (?, ?)', id, code);
  }
  await writeFamilyMemberFood(id, input);
  await writeFamilyMemberTable(id, input);
  return id;
}

export async function updateFamilyMember(
  id: string,
  input: {
    name: string;
    relationship: string;
    conditionCodes: string[];
    includeInMealPlan: boolean;
    allergies?: string[];
    dietTags?: string[];
    restrictions?: string[];
  } & FamilyMemberTable,
): Promise<void> {
  const db = await getDatabase();
  await db.runAsync(
    'UPDATE family_members SET name = ?, relationship = ?, include_in_meal_plan = ? WHERE id = ?',
    input.name.trim(),
    input.relationship.trim(),
    input.includeInMealPlan ? 1 : 0,
    id,
  );
  await db.runAsync('DELETE FROM family_member_conditions WHERE member_id = ?', id);
  for (const code of new Set(input.conditionCodes)) {
    await db.runAsync('INSERT OR IGNORE INTO family_member_conditions (member_id, condition_code) VALUES (?, ?)', id, code);
  }
  await writeFamilyMemberFood(id, input);
  await writeFamilyMemberTable(id, input);
}

export async function deleteFamilyMember(id: string): Promise<void> {
  const db = await getDatabase();
  await db.runAsync('DELETE FROM family_member_conditions WHERE member_id = ?', id);
  await db.runAsync('DELETE FROM family_member_food WHERE member_id = ?', id);
  await db.runAsync('DELETE FROM family_members WHERE id = ?', id);
}

